# Multiple versions and multiple editions might be installed, so we iterate over versions installed.
# If version preference is given, we filter only matching versions, othervise the highest version is picked.
mvs_versions = []
for mvs_path in mvs_paths:
    for version in mvs_path.iterdir():
        if not version.is_dir():
            continue

        # The version should have known editions inside.
        has_known_edition = any(
            edition.name in edition_preferences for edition in version.iterdir()
        )
        if not has_known_edition:
            continue

        # If a version preference was given, only matching versions are accepted.
        if version_preference is not None and version.name != version_preference:
            continue

        mvs_versions.append(version)

mvs_versions = sorted(mvs_versions, key=lambda p: p.name, reverse=True)
